/**
 * @method
 * @name scwin.beforIsur
 * @author Inswave
 * @date 2026. 09. 29
 * @param applId
 * @returns
 * @hidden N
*/
scwin.beforIsur = async function (applId) {
    /* sdd-asis-lifecycle:begin beforIsur — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.JLDINF10100 || { elements: [] });
    let isur_cd = $c.util.getComponent('ipt_isurCd').getValue(); if (isur_cd == null) { isur_cd = ''; }
    if (isur_cd === '') {
        await $c.win.alert("발행기관 코드를 입력하세요.");
        return;
    }
    const url = '/jldinf93000/jldinf93000.xml';
    const params = "isur_cd=" + isur_cd + "&applId=" + applId + "&menuId=11000";
    $.post(url, params, async function(obj) {
            if (obj === '') {
                await $c.win.alert("직전입력분 자료가 없습니다.");
            } else {
                const jsonData = (typeof obj === "string" ? (typeof obj === "string" ? JSON.parse(obj) : obj) : obj);
                $c.util.getComponent('ipt_isuNm').setValue(jsonData.isu_nm);
                $c.util.getComponent('ipt_isuEngNm').setValue(jsonData.isu_eng_nm);
                $('input[name=isu_tp_tp_cd][value="' + jsonData.isu_tp_tp_cd + '"]').attr("checked", true);
                $c.util.getComponent('ipt_isuRnd').setValue(jsonData.isu_rnd);
                $c.util.getComponent('cal_isuDd').setValue($c.date.dateFormat(jsonData.isu_dd));
                $c.util.getComponent('cal_expDd').setValue($c.date.dateFormat(jsonData.exp_dd));
                $c.util.getComponent('ipt_pershrIsuPrc').setValue(jsonData.pershr_isu_prc);
                $c.util.getComponent('ipt_isuShrs').setValue(jsonData.isu_shrs);
                $c.util.getComponent('ipt_stkWrntConvRto').setValue(jsonData.stk_wrnt_conv_rto);
                $('input[name=std_cd_yn][value="' + jsonData.std_cd_yn + '"]').attr("checked", true);
                $('input[name=rd_domFornIsuTpCd][value="' + jsonData.dom_forn_isu_tp_cd + '"]').attr("checked", true);
                $c.util.getComponent('slc_currTpCd').setValue(jsonData.curr_tp_cd);
                $('input[name=elw_rght_tp_kind_cd][value="' + jsonData.elw_rght_tp_kind_cd + '"]').attr("checked", true);
                $c.util.getComponent('slc_fncUlyTpCd').setValue(jsonData.fnc_uly_tp_cd);
                $c.util.getComponent('ipt_ulyIsuCd1').setValue(jsonData.uly_isu_cd1);
                $c.util.getComponent('ipt_ulyIsuNm1').setValue(jsonData.uly_isu_nm1);
                $c.util.getComponent('ipt_vUlyIsuCd1').setValue(jsonData.v_uly_isu_cd1);
                $c.util.getComponent('ipt_objInstNm').setValue(jsonData.uly_isu_nm1);
                $c.util.getComponent('ipt_objInstCd').setValue(jsonData.v_uly_isu_cd1);
                $c.util.getComponent('ipt_ulyContn').setValue(jsonData.uly_isu_cd1);
                $c.util.getComponent('ipt_ulyCompstRto1').setValue(jsonData.uly_compst_rto1);
                $c.util.getComponent('slc_elwObjIdxTpCd').setValue(jsonData.elw_obj_idx_tp_cd);
                $c.util.getComponent('ipt_miscIdxContn').setValue(jsonData.misc_idx_contn);
                $c.util.getComponent('ipt_miscFncUlyContn').setValue(jsonData.misc_fnc_uly_contn);
                $('input[name=rght_tp_cd][value="' + jsonData.rght_tp_cd + '"]').attr("checked", true);
                $('input[name=exer_tp_cd][value="' + jsonData.exer_tp_cd + '"]').attr("checked", true);
                $c.util.getComponent('ipt_nusualIsuCondContn').setValue(jsonData.nusual_isu_cond_contn);
                const cfiCd = jsonData.cfi_cd.toString();
                $c.util.getComponent('slc_attr01').setValue(cfiCd.substring(2, 3));
                $c.util.getComponent('slc_attr02').setValue(cfiCd.substring(3, 4));
                $c.util.getComponent('slc_attr03').setValue(cfiCd.substring(4, 5));
                $c.util.getComponent('slc_attr04').setValue(cfiCd.substring(5, 6));
                scwin.chg_attr();
                $c.util.getComponent('ipt_fisnVal').setValue(jsonData.fisn_val);
                if (jsonData.std_cd_apct_tp_cd != null) {
                    const vl = jsonData.std_cd_apct_tp_cd.toString();
                    const tObj = $('input[name=std_cd_apct_tp_cd][value="' + vl + '"]');
                    if (tObj.length > 0) {
                        $(tObj)[0].checked = true;
                    }
                }
                if (jsonData.appl_com_nm != null) {
                    $c.util.getComponent('ipt_applComNm').setValue(jsonData.appl_com_nm.toString());
                }
                if (jsonData.apct_nm != null) {
                    $c.util.getComponent('ipt_apctNm').setValue(jsonData.apct_nm.toString());
                }
                if (jsonData.encryp_apct_email != null) {
                    const email = jsonData.encryp_apct_email.toString();
                    const emails = email.split("@");
                    if (emails.length > 0) {
                        $c.util.getComponent('ipt_encrypApctEmail1').setValue(emails[0]);
                    }
                    if (emails.length > 1) {
                        $c.util.getComponent('ipt_encrypApctEmail2').setValue(emails[1]);
                    }
                }
                if (jsonData.apct_tel_no != null) {
                    const tel = jsonData.apct_tel_no.toString();
                    const tels = tel.split("-");
                    if (tels.length > 0) {
                        $c.util.getComponent('ipt_apctTelNo1').setValue(tels[0]);
                    }
                    if (tels.length > 1) {
                        $c.util.getComponent('ipt_apctTelNo2').setValue(tels[1]);
                    }
                    if (tels.length > 2) {
                        $c.util.getComponent('ipt_apctTelNo3').setValue(tels[2]);
                    }
                }
                if (jsonData.apct_fax_no != null) {
                    const fax = jsonData.apct_fax_no.toString();
                    const faxs = fax.split("-");
                    if (faxs.length > 0) {
                        $c.util.getComponent('ipt_apctFaxNo1').setValue(faxs[0]);
                    }
                    if (faxs.length > 1) {
                        $c.util.getComponent('ipt_apctFaxNo2').setValue(faxs[1]);
                    }
                    if (faxs.length > 2) {
                        $c.util.getComponent('ipt_apctFaxNo3').setValue(faxs[2]);
                    }
                }
                if (jsonData.encryp_cellphone_no != null && jsonData.encryp_cellphone_no !== '') {
                    const hp = jsonData.encryp_cellphone_no.toString();
                    const hps = hp.split("-");
                    if (hps.length > 0) {
                        $c.util.getComponent('ipt_apctHpNo1').setValue(hps[0]);
                    }
                    if (hps.length > 1) {
                        $c.util.getComponent('ipt_apctHpNo2').setValue(hps[1]);
                    }
                    if (hps.length > 2) {
                        $c.util.getComponent('ipt_apctHpNo3').setValue(hps[2]);
                    }
                }
                if (applId === "" || applId === "undefined") {
                    await $c.win.alert("직전 입력내용이 반영되었습니다.\n\r수정후 신청하시기 바랍니다.");
                } else {
                    await $c.win.alert("기신청한 내용이 반영되었습니다.\n\r수정후 재신청하시기 바랍니다.");
                }
            }
    });
    /* sdd-asis-lifecycle:end */
};


